-- FinDost AI schema (generated by backend/scripts/export_schema.py)

CREATE TABLE IF NOT EXISTS ai_usage (
	id VARCHAR(36) NOT NULL, 
	business_id VARCHAR(36) NOT NULL, 
	day DATE NOT NULL, 
	task VARCHAR(24) NOT NULL, 
	calls INTEGER NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_ai_usage_day_task UNIQUE (business_id, day, task), 
	FOREIGN KEY(business_id) REFERENCES businesses (id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS ix_ai_usage_business_id ON ai_usage (business_id);
ALTER TABLE public."ai_usage" ENABLE ROW LEVEL SECURITY;

CREATE TABLE IF NOT EXISTS audit_events (
	id VARCHAR(36) NOT NULL, 
	business_id VARCHAR(36) NOT NULL, 
	entity_type VARCHAR(24) NOT NULL, 
	entity_id VARCHAR(36) NOT NULL, 
	action VARCHAR(16) NOT NULL, 
	actor_id VARCHAR(64) NOT NULL, 
	changes JSON NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(business_id) REFERENCES businesses (id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS ix_audit_events_created_at ON audit_events (created_at);
CREATE INDEX IF NOT EXISTS ix_audit_events_entity_id ON audit_events (entity_id);
CREATE INDEX IF NOT EXISTS ix_audit_events_business_id ON audit_events (business_id);
ALTER TABLE public."audit_events" ENABLE ROW LEVEL SECURITY;
